for r in range(h):
    for c in range(w):
        if input_grid[r][c] == 0:
            zero_positions.append((r, c))

print(f"Total 0s in input: {len(zero_positions)}")

# Count neighbors of each 0 (8-directional)
def count_neighbors(grid, r, c):
    count = 0
    for dr in (-1, 0, 1):
        for dc in (-1, 0, 1):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == 1:
                    count += 1
    return count

# Classify 0s
unchanged_zeros = []
changed_zeros = []
for pos in zero_positions:
    r, c = pos
    n = count_neighbors(input_grid, r, c)
    if output_grid[r][c] == 8:
        changed_zeros.append((r, c, n))
    else:
        unchanged_zeros.append((r, c, n))

print(f"\nChanged 0s (count_neighbors):")
